50	     * {@code addressLine2} appended after a single space (when present); otherwise fall back to
51	     * the normalized flat {@code address} for backward compatibility.
52	     */
53	    default String composeAddress(OwnerFieldsDto ownerDto) {
54	        String line1 = normalizeAddress(ownerDto.getAddressLine1());
55	        if (line1 == null || line1.isBlank()) {
56	            return normalizeAddress(ownerDto.getAddress());
